"""Live rollout eval on hand-written, messy customer chats (not generated by the simulator).

Each case opens with what a real customer might type (Pidgin, typos, several details in one
message, corrections). After the scripted openers run out, an oracle answers whatever the
assistant asks using the ground truth. We score the final <order> against the truth and count turns.

Usage: python training/eval_live.py
"""
from __future__ import annotations

import asyncio
import json
import re
import sys
from pathlib import Path

import tinker
from tinker import types
from tinker_cookbook import renderers
from tinker_cookbook.tokenizer_utils import get_tokenizer

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "app"))
sys.path.insert(0, str(HERE))
from engine import ScriptedEngine, parse_reply  # noqa: E402
from eval import SLOT_PATTERNS, score_order  # noqa: E402
from menu import LENGTHS, SERVICES, STYLES, SYSTEM_PROMPT  # noqa: E402

GREETING = "Hi love, welcome to Sugar Nails! 💅 Sugar is on a client right now, so I'll get you booked. What's your name?"

def G(name, phone, services, style, colours, length, shape, notes, time):
    return dict(name=name, phone=phone, services=services, style=style, colours=colours, length=length, shape=shape, notes=notes, time=time)

CASES = [
    (["Amarachi", "07062223344", "abeg I wan do acrylic, long coffin, chrome. wine colour"],
     G("Amarachi", "07062223344", ["acrylic_full"], "chrome", ["Wine"], "long", "Coffin", "None", "Today, evening")),
    (["my name na Funmi Adeyemi", "o8o3 is wrong sorry 08034445566", "i want pedicure and gel for toes"],
     G("Funmi Adeyemi", "08034445566", ["pedicure", "gel_toes"], "plain", ["Red"], "natural", "n/a", "None", "Right now (walk-in)")),
    (["Ify", "+234 816 777 8899", "Remove my old acrylic first then do gel-x extensions", "french tip", "milky white"],
     G("Ify", "08167778899", ["removal", "gelx"], "french", ["Milky white"], "medium", "Almond", "None", "Tomorrow, morning")),
    (["Hello good afternoon", "Zee", "09051112233", "BIAB overlay pls, I like that cat eye thing", "gold"],
     G("Zee", "09051112233", ["biab"], "cat_eye", ["Gold"], "natural", "Oval", "Sensitive skin", "Today, afternoon")),
    (["Tolani", "0701 234 5678", "press on nails, extra long stiletto, with stones and bling", "black and silver"],
     G("Tolani", "07012345678", ["press_on"], "stones", ["Black", "Silver"], "xl", "Stiletto", "None", "Tomorrow, afternoon")),
    (["call me Kiki", "08129990001", "just manicure today", "my left thumb nail broke o"],
     G("Kiki", "08129990001", ["manicure"], "plain", ["Nude"], "natural", "Square", "Broken nail on left thumb", "Right now (walk-in)")),
    (["Hauwa Musa", "08025556677", "acrylic refill + 3d flowers", "baby pink", "medium", "square"],
     G("Hauwa Musa", "08025556677", ["refill"], "flowers_3d", ["Baby pink"], "medium", "Square", "None", "Today, evening")),
    (["Mercy", "07039876543", "gel polish on my fingers, marble design, white and gold", "round shape abeg"],
     G("Mercy", "07039876543", ["gel_hands"], "marble", ["Milky white", "Gold"], "natural", "Round", "None", "Today, afternoon")),
    (["I'm Rukky", "08061230987", "gelx", "ombre", "nude and baby pink", "XL", "coffin", "I dey allergic to latex"],
     G("Rukky", "08061230987", ["gelx"], "ombre", ["Nude", "Baby pink"], "xl", "Coffin", "Allergic to latex gloves", "Right now (walk-in)")),
    (["Precious", "0814 000 1122", "full set acrylic with hand painted design, short squoval, hot pink"],
     G("Precious", "08140001122", ["acrylic_full"], "nail_art", ["Hot pink"], "short", "Squoval", "None", "Tomorrow, morning")),
    (["na Simi", "07087776655", "spa pedicure and normal manicure"],
     G("Simi", "07087776655", ["pedicure", "manicure"], "plain", ["Coral"], "natural", "Oval", "None", "Today, evening")),
    (["Joy Eze", "08187654321", "gel polish", "plain", "emerald green", "almond", "pls no cutting my cuticles"],
     G("Joy Eze", "08187654321", ["gel_hands"], "plain", ["Emerald green"], "natural", "Almond", "Prefers no cutting of cuticles", "Today, afternoon")),
]


def oracle(question: str, goal: dict) -> str:
    q = question.split("\n")[0]
    for slot in ["phone", "services", "style", "colours", "length", "shape", "notes", "time", "name"]:
        if re.search(SLOT_PATTERNS[slot], q, re.I):
            v = goal[slot]
            if slot == "services": return ", ".join(SERVICES[s][0] for s in v)
            if slot == "style": return STYLES[v][0]
            if slot == "colours": return ", ".join(v)
            if slot == "length": return LENGTHS[v][0] if v != "natural" else "Short"
            if slot == "notes": return "No allergies" if v == "None" else v
            return str(v)
    return "okay"


async def rollout(respond, openers, goal, max_turns=12):
    msgs = [{"role": "assistant", "content": GREETING}]
    queue = list(openers)
    for turn in range(max_turns):
        user = queue.pop(0) if queue else oracle(msgs[-1]["content"], goal)
        msgs.append({"role": "user", "content": user})
        reply = await respond(msgs)
        msgs.append({"role": "assistant", "content": reply})
        p = parse_reply(reply)
        if p["order"] is not None and not queue:
            return p["order"], turn + 1, msgs
    return None, max_turns, msgs


async def main():
    tok = get_tokenizer("Qwen/Qwen3-8B")
    ren = renderers.get_renderer("qwen3_disable_thinking", tok)
    svc = tinker.ServiceClient()
    ck = json.loads((HERE / "results/checkpoint.json").read_text())
    params = types.SamplingParams(max_tokens=400, temperature=0.0, stop=ren.get_stop_sequences())

    def model_responder(sampler):
        async def respond(msgs):
            prompt = ren.build_generation_prompt([{"role": "system", "content": SYSTEM_PROMPT}] + msgs)
            r = await sampler.sample_async(prompt=prompt, num_samples=1, sampling_params=params)
            m, _ = ren.parse_response(r.sequences[0].tokens)
            return m["content"] if isinstance(m["content"], str) else renderers.get_text_content(m)
        return respond

    rules = ScriptedEngine()

    async def rule_respond(msgs):
        return rules.respond([m["content"] for m in msgs if m["role"] == "user"])

    engines = {"base": model_responder(svc.create_sampling_client(base_model="Qwen/Qwen3-8B")),
               "fine_tuned": model_responder(svc.create_sampling_client(model_path=ck["sampler_path"])),
               "rule_based_fallback": rule_respond}
    summary, logs = {}, {}
    for name, fn in engines.items():
        outs = await asyncio.gather(*[rollout(fn, o, g) for o, g in CASES])
        scores = [score_order(o, g) for (o, _, _), (_, g) in zip(outs, CASES)]
        summary[name] = {
            "booking_completed": round(sum(o is not None for o, _, _ in outs) / len(CASES), 3),
            "field_accuracy": round(sum(s["field_acc"] for s in scores) / len(CASES), 3),
            "exact_order": round(sum(s["exact"] for s in scores) / len(CASES), 3),
            "price_correct": round(sum(s["price"] for s in scores) / len(CASES), 3),
            "mean_turns": round(sum(t for _, t, _ in outs) / len(CASES), 2),
        }
        logs[name] = [m for _, _, m in outs]
        print(name, summary[name], flush=True)
    (HERE / "results/eval_live_results.json").write_text(json.dumps({"n_cases": len(CASES), "results": summary}, indent=1))
    (HERE / "results/eval_live_transcripts.json").write_text(json.dumps(logs, indent=1, ensure_ascii=False))


if __name__ == "__main__":
    asyncio.run(main())
